<script setup>
import {inject as injectAdminConfirmation} from 'vue'
const {confirmAction}=injectAdminConfirmation('admin')
import {ref,reactive,computed,inject} from 'vue'
import {useAuthStore} from '../../../stores/auth'
import {useApiState,useApiMutation} from '../../../composables/useApiState'
import {useUnsavedForm} from '../../../composables/useUnsavedForm'
import {closuresApi} from '../../../api/businessHours.api'
import AdminSectionHeading from '../AdminSectionHeading.vue'
import AdminModal from '../AdminModal.vue'
import ApiFeedback from '../catalog/ApiFeedback.vue'
import ApiPagination from '../catalog/ApiPagination.vue'
const props=defineProps({branch:{type:String,required:true}}),emit=defineEmits(['updated','dirty','busy'])
const auth=useAuthStore(),state=useApiState(),mutation=useApiMutation(),{notify}=inject('admin'),page=ref(1),open=ref(false),record=ref(null),deleting=ref(null),saving=ref(false),baseline=ref('')
const form=reactive({starts_at:'',ends_at:'',reason:'',is_active:true})
const dirty=computed(()=>open.value&&JSON.stringify(form)!==baseline.value)
useUnsavedForm(dirty,saving,emit)
function load(current=page.value){page.value=current;return state.run(signal=>closuresApi.list(props.branch,current,signal))}
function edit(row=null){record.value=row;mutation.error.value=null;Object.assign(form,{starts_at:row?.starts_at?.slice(0,19)||'',ends_at:row?.ends_at?.slice(0,19)||'',reason:row?.reason||'',is_active:row?.is_active??true});baseline.value=JSON.stringify(form);open.value=true}
function canClose(){return !saving.value&&(!dirty.value||confirm('تجاهل تغييرات الإغلاق؟'))}
async function save(){if(saving.value)return;if(form.is_active&&!(await confirmAction('تأكيد الإغلاق خلال الفترة المحددة؟ قد تتوقف الطلبات الجديدة.')))return;saving.value=true;try{const body={...form,starts_at:form.starts_at===record.value?.starts_at?.slice(0,19)?record.value.starts_at:form.starts_at+(form.starts_at.length===16?':00Z':'Z'),ends_at:form.ends_at===record.value?.ends_at?.slice(0,19)?record.value.ends_at:form.ends_at+(form.ends_at.length===16?':00Z':'Z'),reason:form.reason||null};const result=await mutation.run(()=>record.value?closuresApi.update(props.branch,record.value.uuid,body):closuresApi.create(props.branch,body));if(result.ok){open.value=false;notify('تم حفظ الإغلاق المؤقت.');await load();emit('updated')}else if([404,409].includes(mutation.error.value?.status)){await load();emit('updated')}}finally{saving.value=false}}
async function remove(){if(saving.value)return;saving.value=true;try{const result=await mutation.run(()=>closuresApi.remove(props.branch,deleting.value.uuid));if(result.ok){deleting.value=null;notify('تم حذف الإغلاق.');if(state.data.value?.data.length===1&&page.value>1)page.value--;await load();emit('updated')}else if([404,409].includes(mutation.error.value?.status))await load()}finally{saving.value=false}}
void load()
</script>
<template><section class="panel closures-panel"><AdminSectionHeading icon="clock">الإغلاقات المؤقتة والاستثناءات<template #actions><button v-if="auth.can('branches.closures.create')" class="button" :disabled="saving" @click="edit()">إضافة إغلاق مؤقت</button></template></AdminSectionHeading><p class="form-note">الفترات بالتوقيت العالمي UTC، وليست بتوقيت جهازك. الإغلاق النشط يتقدم على ساعات العمل، ويمكن أن تتداخل الإغلاقات. السبب ملاحظة إدارية ولا يُعرض للعملاء.</p><ApiFeedback :loading="state.loading.value" :error="state.error.value" :empty="state.data.value?.data.length===0" @retry="load()"/><div v-if="state.data.value?.data.length" class="table-wrap"><table v-admin-table><thead><tr><th>البداية (UTC)</th><th>النهاية (UTC)</th><th>الحالة</th><th>السبب</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="row in state.data.value.data" :key="row.uuid"><td><div class="admin-cell-value"><bdi>{{ row.starts_at }}</bdi></div></td><td><div class="admin-cell-value"><bdi>{{ row.ends_at }}</bdi></div></td><td><div class="admin-cell-value"><span class="badge" :class="row.is_active?'good':'off'">{{ row.is_active?'نشط':'معطّل' }}</span></div></td><td class="setting-value"><div class="admin-cell-value">{{ row.reason||'—' }}</div></td><td><div class="admin-cell-value"><div class="admin-row-actions"><button v-if="auth.can('branches.closures.update')" class="row-button" :disabled="saving" @click="edit(row)">تعديل / تفعيل</button><button v-if="auth.can('branches.closures.delete')" class="row-button danger" :disabled="saving" @click="mutation.error.value=null;deleting=row">حذف</button></div></div></td></tr></tbody></table></div><ApiPagination :meta="state.data.value?.meta" :links="state.data.value?.links" :busy="state.loading.value||saving" @page="load"/><AdminModal :open="open" :title="record?'تعديل الإغلاق المؤقت':'إغلاق مؤقت جديد'" :busy="saving" :before-close="canClose" @update:open="open=$event" @submit="save"><label v-for="[key,label] in [['starts_at','البداية بتوقيت UTC'],['ends_at','النهاية بتوقيت UTC']]" :key="key" class="field">{{ label }}<input v-model="form[key]" :name="key" type="datetime-local" step="1" required :disabled="saving"><small v-for="message in mutation.error.value?.errors?.[key]||[]" :key="message" class="field-error" role="alert">{{ message }}</small></label><label class="field">السبب الإداري (اختياري)<textarea v-model="form.reason" maxlength="1000" :disabled="saving"/></label><label class="check"><input v-model="form.is_active" type="checkbox" :disabled="saving">تفعيل الإغلاق</label><button class="button" :disabled="saving">{{ saving?'جارٍ الحفظ…':'حفظ الإغلاق' }}</button><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></AdminModal><AdminModal :open="!!deleting" title="حذف الإغلاق المؤقت؟" :busy="saving" @update:open="deleting=null" @submit="remove"><p>حذف الإغلاق قد يعيد استقبال الطلبات إذا كان الفرع مفتوحًا وفق جدوله.</p><button class="button" :disabled="saving">تأكيد الحذف</button><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></AdminModal></section></template>
